-- 23 new nameplates and sharp artwork for the existing 13.
-- Existing IDs, ownership and active selections are preserved. No inventory grants.
ON CONFLICT (id) DO UPDATE SET
 name=EXCLUDED.name,description=EXCLUDED.description,asset_url=EXCLUDED.asset_url,
 preview_url=EXCLUDED.preview_url,fps=EXCLUDED.fps,duration_ms=EXCLUDED.duration_ms,
 shade_opacity=EXCLUDED.shade_opacity;
